/** QR codes (payment links, invoice links, two-factor setup). Rendered in the browser as inline SVG. */
import qrcode from 'qrcode-generator';

document.querySelectorAll('[data-qr]').forEach((element) => {
    const qr = qrcode(0, 'M');
    qr.addData(element.dataset.qr);
    qr.make();
    // The SVG is generated by the library from the data only; nothing user-supplied is injected as markup
    element.innerHTML = qr.createSvgTag({ cellSize: Number(element.dataset.qrSize || 4), margin: 2, scalable: true });
    const svg = element.querySelector('svg');
    if (svg) {
        svg.setAttribute('role', 'img');
        svg.setAttribute('aria-label', element.dataset.qrLabel || 'QR code');
        svg.style.width = '100%';
        svg.style.height = 'auto';
        svg.style.background = '#fff';
    }
});
